import java.util.*;

class Solution {
  private static final long MOD = 1_000_000_007L;

  public int countPartitions(int[] nums, int k) {
    long total = 0;
    for (int value : nums) total += value;
    if (total < 2L * k) return 0;
    long[] dp = new long[k];
    dp[0] = 1;
    for (int value : nums) {
      for (int sum = k - 1; sum >= value; sum--) {
        dp[sum] = (dp[sum] + dp[sum - value]) % MOD;
      }
    }
    long invalid = 0;
    for (long ways : dp) invalid = (invalid + ways) % MOD;
    long all = power(2, nums.length);
    return (int) ((all - 2 * invalid % MOD + MOD) % MOD);
  }

  private long power(long base, int exponent) {
    long result = 1;
    while (exponent > 0) {
      if ((exponent & 1) != 0) result = result * base % MOD;
      base = base * base % MOD;
      exponent >>= 1;
    }
    return result;
  }
}
